      const where = clauses.length > 0 ? `WHERE ${clauses.join(" AND ")}` : "";
      const limit = Math.max(1, Math.min(filters.limit ?? 1000, 1e4));
      const dir = filters.order === "desc" ? "DESC" : "ASC";
