    if (token === "--check-drift" || token === "--drift") {
      opts.drift = true;
      continue;
    }
    if (token === "--specialists" || token === "--check-specialists") {
      opts.specialists = true;
      continue;
    }
    if (token === "--pr-drift") {
      opts.pr_drift = true;
      continue;
    }
    if (token === "--reap-dead-jobs") {
      opts.reap_dead_jobs = true;
      continue;
    }
    if (token === "--dry-run") {
      opts.dry_run = true;
      continue;
    }
